style.css:
/* =======================================
   Theme Roblox seguro – Fondo, texto y botones
   ======================================= */

/* Fondo de toda la página */
html {
    background: url("https://i.pinimg.com/736x/fc/ab/ca/fcabcae955c0f7158d12d6a0a0547654.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #f2f2f2 !important;
}

/* Texto principal */
span, p, a, h1, h2, h3, h4, h5, h6 {
    color: #f2f2f2 !important;
}

/* Botones violetas */
button {
    background-color: #8a2be2 !important;
    color: #ffffff !important;
    border-radius: 6px !important;
    border: none !important;
    padding: 5px 10px !important;
    cursor: pointer !important;
}

/* Botones al pasar el mouse */
button:hover {
    background-color: #7a1ee0 !important;
}

/* Enlaces al pasar el mouse */
a:hover {
    color: #dcdcdc !important;
}
